#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    LAB_CATEGORY_BY_INDEX, LAB_CATEGORY_RESEARCH_COUNT
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Emit lab categories from the versioned lab-categories.json fixture.
 *
 * Maps fixture container names to the SDK's curated categories and writes a TypeScript
 * module, preserving the finer distinctions in the hand-owned catalog.
 *
 * ## Why this fills gaps rather than replacing the hand catalog
 *
 * The game groups labs into eleven containers. The hand-owned `LAB_CATALOG` uses fifteen
 * categories, because it splits two of them further:
 *
 *   Cards Researches            -> `Cards` AND `Card Mastery`
 *   Battle Condition Researches -> four `Battle Condition (...)` sub-categories
 *
 * That curation is real information the game does not express, so flattening every lab onto
 * the eleven would LOSE detail — a worse outcome than the gap it fixes. The two ambiguous
 * groups are therefore emitted as `null`: a lab in one of them that is missing from the
 * hand catalog stays uncategorised and trips the coverage guard, so a human picks the
 * sub-category instead of the generator guessing.
 *
 * Today that costs nothing: every Cards and Battle Condition lab is already catalogued, and
 * the six labs this closes are all in unambiguous groups.
 *
 * Usage:  node scripts/build-lab-categories.mjs [--facts <dir>]
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

const HERE = path.dirname(fileURLToPath(import.meta.url))
const SDK = path.join(HERE, '..')
const REPO = path.join(SDK, '..', '..')

const OUT = path.join(SDK, 'src', 'data', 'generated', 'labs-categories.generated.ts')

/**
 * Game UI container -> the SDK's canonical category.
 *
 * `null` means "the SDK draws a finer distinction here than the game does"; see the header.
 * A name absent from this table is a new container and stops the build, because silently
 * dropping a whole group is exactly the failure this file exists to prevent.
 */
const CATEGORY_BY_CONTAINER = {
  'Main Researches': 'Main',
  'Attack Researches': 'Attack',
  'Defense Researches': 'Defense',
  'Utility Researches': 'Utility',
  'Ultimate Weapons Researches': 'Ultimate Weapon',
  'Perks Researches': 'Perks',
  'Bots Researches': 'Bots',
  'Enemies Researches': 'Enemies',
  'Modules Researches': 'Modules',
  'Cards Researches': null,
  'Battle Condition Researches': null,
}

/**
 * Read committed facts/v<version>/lab-categories.json by default.
 * TOWER_FACTS_VERSION selects the version; --facts <dir> selects a fixture directory.
 */
function resolveFactsDir() {
  const flag = process.argv.indexOf('--facts')
  if (flag >= 0 && process.argv[flag + 1]) return process.argv[flag + 1]
  const version = (process.env.TOWER_FACTS_VERSION ?? '29.0.0').replace(/^v/i, '')
  return path.join(SDK, 'facts', `v${version}`)
}

const factsDir = resolveFactsDir()
const source = path.join(factsDir, 'lab-categories.json')
if (!fs.existsSync(source)) {
  console.error(`no lab-categories.json in ${factsDir}\n`
    + '  Supply the versioned fixture there, or select its directory with --facts <dir>.\n'
    + '  TOWER_FACTS_VERSION selects the default facts/v<version> directory.')
  process.exit(1)
}

const payload = JSON.parse(fs.readFileSync(source, 'utf8'))
const unknown = Object.keys(payload.groups ?? {}).filter(name => !(name in CATEGORY_BY_CONTAINER))
if (unknown.length) {
  console.error(`unmapped UI container(s): ${unknown.join(', ')}\n`
    + '  Add them to CATEGORY_BY_CONTAINER. A new group is a new part of the game, not '
    + 'something to skip.')
  process.exit(1)
}

const entries = []
let mapped = 0
let deferred = 0
for (const [index, container] of Object.entries(payload.categoryByIndex ?? {})) {
  const category = CATEGORY_BY_CONTAINER[container]
  if (category == null) { deferred += 1; continue }
  entries.push([Number(index), category, container])
  mapped += 1
}
entries.sort((a, b) => a[0] - b[0])

const body = entries.map(([index, category, container]) =>
  `  ${index}: '${category}',${' '.repeat(Math.max(1, 22 - category.length))}// ${container}`)
  .join('\n')

const file = `/* GENERATED by scripts/build-lab-categories.mjs — do not edit. */
/**
 * Lab categories by research index, generated from the versioned category fixture.
 *
 * The fixture groups ${payload.researchCount} research slots. This module keeps those
 * groupings separate from the SDK's finer catalog categories.
 *
 * Labs in \`Cards Researches\` and \`Battle Condition Researches\` are deliberately ABSENT.
 * The SDK splits those two containers further — \`Cards\` vs \`Card Mastery\`, and four
 * \`Battle Condition (...)\` sub-categories — and that curation is information the game does
 * not carry. Flattening them onto the container name would lose it, so those labs rely on
 * the hand-owned catalog and, if one is ever missing from it, trip the coverage guard
 * instead of being guessed at.
 */
export const LAB_CATEGORY_BY_INDEX: Readonly<Record<number, string>> = {
${body}
}

/** Research slots the game defines, at the build this was generated from. */
export const LAB_CATEGORY_RESEARCH_COUNT = ${payload.researchCount}
`

fs.mkdirSync(path.dirname(OUT), { recursive: true })
fs.writeFileSync(OUT, file, 'utf8')
console.log(`wrote ${path.relative(REPO, OUT)}`)
console.log(`  ${mapped} labs mapped, ${deferred} left to the hand catalog `
  + '(Cards / Battle Condition are finer there)')
